import java.util.*;
final class Builtins {
    static final class RuntimeIssue extends RuntimeException {
        final Lexer.Position pos;
        RuntimeIssue(Lexer.Position pos, String message) {
            super(message);
            this.pos = pos;
        }
    }
    static String format(List<ValuesFields.Value> arguments, Lexer.Position pos) {
        String fmt = ValuesFields.text(arguments.getFirst());
        StringBuilder result = new StringBuilder();
        int index = 0, argument = 1;
        while (index < fmt.length()) {
            char c = fmt.charAt(index++);
            if (c != '%') {
                result.append(c);
                continue;
            }
            if (index < fmt.length() && fmt.charAt(index) == '%') {
                result.append('%');
                index++;
                continue;
            }
            boolean left = false, zero = false;
            while (index < fmt.length() && (fmt.charAt(index) == '-' || fmt.charAt(index) == '0')) {
                if (fmt.charAt(index) == '-')
                    left = true;
                else
                    zero = true;
                index++;
            }
            int width = 0;
            while (index < fmt.length() && Lexer.digit(fmt.charAt(index)))
                width = 10 * width + fmt.charAt(index++) - '0';
            Integer precision = null;
            if (index < fmt.length() && fmt.charAt(index) == '.') {
                index++;
                int value = 0;
                while (index < fmt.length() && Lexer.digit(fmt.charAt(index)))
                    value = 10 * value + fmt.charAt(index++) - '0';
                precision = value;
            }
            if (index == fmt.length() || "discxo".indexOf(fmt.charAt(index)) < 0)
                throw new RuntimeIssue(pos, "invalid format");
            char conversion = fmt.charAt(index++);
            if (argument == arguments.size())
                throw new RuntimeIssue(pos, "not enough arguments");
            ValuesFields.Value value = arguments.get(argument++);
            boolean numeric = "dixo".indexOf(conversion) >= 0;
            String body;
            if (numeric) {
                int n = ValuesFields.numeric(value), radix = conversion == 'x'   ? 16
                                                             : conversion == 'o' ? 8
                                                                                 : 10;
                String digits = Long.toString(Math.abs((long)n), radix);
                if (precision != null) {
                    if (precision == 0 && n == 0)
                        digits = "";
                    else if (digits.length() < precision)
                        digits = "0".repeat(precision - digits.length()) + digits;
                }
                body = (n < 0 ? "-" : "") + digits;
            } else if (conversion == 's') {
                body = ValuesFields.text(value);
                if (precision != null)
                    body = body.substring(0, Math.min(body.length(), precision));
            } else if (value.kind() == ValuesFields.Kind.NUMBER ||
                       value.kind() == ValuesFields.Kind.STRNUM) {
                int code = ValuesFields.numeric(value);
                if (code != 10 && (code < 32 || code > 126))
                    throw new RuntimeIssue(pos, "invalid character code");
                body = String.valueOf((char)code);
            } else {
                body = ValuesFields.text(value);
                body = body.substring(0, Math.min(1, body.length()));
            }
            int missing = width - body.length();
            if (missing > 0) {
                if (left)
                    body += " ".repeat(missing);
                else if (numeric && zero && precision == null)
                    body = body.startsWith("-") ? "-"
                                                      + "0".repeat(missing) + body.substring(1)
                                                : "0".repeat(missing) + body;
                else
                    body = " ".repeat(missing) + body;
            }
            result.append(body);
        }
        return result.toString();
    }
    static ValuesFields.Value invoke(String name, List<ValuesFields.Value> args,
                                     Lexer.Position pos) {
        if (name.equals("sprintf"))
            return ValuesFields.string(format(args, pos));
        if (name.equals("int"))
            return ValuesFields.number(ValuesFields.numeric(args.getFirst()));
        String text = ValuesFields.text(args.getFirst());
        if (name.equals("substr")) {
            int start = ValuesFields.numeric(args.get(1)),
                end = args.size() == 3 ? start + ValuesFields.numeric(args.get(2))
                                       : text.length() + 1;
            start = Math.max(start, 1);
            end = Math.min(end, text.length() + 1);
            return ValuesFields.string(end > start ? text.substring(start - 1, end - 1) : "");
        }
        if (name.equals("index")) {
            String sought = ValuesFields.text(args.get(1));
            return ValuesFields.number(sought.isEmpty() ? 0 : text.indexOf(sought) + 1);
        }
        StringBuilder result = new StringBuilder();
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            if (name.equals("toupper") && c >= 'a' && c <= 'z')
                c = (char)(c - 'a' + 'A');
            else if (name.equals("tolower") && c >= 'A' && c <= 'Z')
                c = (char)(c - 'A' + 'a');
            result.append(c);
        }
        return ValuesFields.string(result.toString());
    }
}

import java.util.*;
final class Lexer {
    record Position(int line, int column) implements Comparable<Position> {
        public int compareTo(Position other) {
            int order = Integer.compare(line, other.line);
            return order != 0 ? order : Integer.compare(column, other.column);
        }
        public String toString() { return line + ":" + column; }
    }
    enum Kind { NUMBER, STRING, NAME, FUNCNAME, BUILTIN, KEYWORD, SYMBOL, NEWLINE, END }
    record Token(Kind kind, String text, String value, Position pos) {}
    static final class SyntaxIssue extends RuntimeException {
        final Position pos;
        SyntaxIssue(Position pos) { this.pos = pos; }
    }
    static final Set<String> KEYWORDS =
                                 Set.of("BEGIN", "END", "function", "if", "else", "while", "for",
                                        "do", "break", "continue", "next", "exit", "return",
                                        "delete", "in", "getline", "print", "printf"),
                             BUILTINS = Set.of("length", "substr", "index", "split", "sprintf",
                                               "toupper", "tolower", "close", "int"),
                             PAIRS = Set.of("+=", "-=", "*=", "/=", "%=", "^=", "==", "<=", ">=",
                                            "!=", "++", "--", "&&", "||", ">>");
    static boolean letter(char c) {
        return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c == '_';
    }
    static boolean digit(char c) { return c >= '0' && c <= '9'; }
    static List<Token> tokenize(String source) {
        List<Token> result = new ArrayList<>();
        int index = 0, line = 1, column = 1;
        while (index < source.length()) {
            char c = source.charAt(index);
            Position start = new Position(line, column);
            if (c == ' ') {
                index++;
                column++;
                continue;
            }
            if (c == '\\' && index + 1 < source.length() && source.charAt(index + 1) == '\n') {
                index += 2;
                line++;
                column = 1;
                continue;
            }
            if (c == '#') {
                int end = source.indexOf('\n', index);
                if (end < 0)
                    end = source.length();
                column += end - index;
                index = end;
                continue;
            }
            if (c == '\n') {
                result.add(new Token(Kind.NEWLINE, "\n", null, start));
                index++;
                line++;
                column = 1;
                continue;
            }
            int end = index + 1;
            Kind kind;
            String value = null;
            if (digit(c)) {
                while (end < source.length() && digit(source.charAt(end)))
                    end++;
                kind = Kind.NUMBER;
                value = source.substring(index, end);
            } else if (letter(c)) {
                while (end < source.length() &&
                       (letter(source.charAt(end)) || digit(source.charAt(end))))
                    end++;
                String word = source.substring(index, end);
                kind = KEYWORDS.contains(word)                              ? Kind.KEYWORD
                       : BUILTINS.contains(word)                            ? Kind.BUILTIN
                       : end < source.length() && source.charAt(end) == '(' ? Kind.FUNCNAME
                                                                            : Kind.NAME;
            } else if (c == '"') {
                StringBuilder text = new StringBuilder();
                while (end < source.length() && source.charAt(end) != '"') {
                    char next = source.charAt(end);
                    if (next == '\n')
                        throw new SyntaxIssue(start);
                    if (next == '\\') {
                        if (end + 1 == source.length())
                            throw new SyntaxIssue(new Position(line, column + end - index));
                        char escaped = source.charAt(end + 1);
                        if ("nt\\\"/".indexOf(escaped) < 0)
                            throw new SyntaxIssue(new Position(line, column + end - index));
                        text.append(switch (escaped) {
                            case 'n' -> '\n';
                            case 't' -> '\t';
                            default -> escaped;
                        });
                        end += 2;
                    } else {
                        text.append(next);
                        end++;
                    }
                }
                if (end == source.length())
                    throw new SyntaxIssue(start);
                end++;
                kind = Kind.STRING;
                value = text.toString();
            } else if (end < source.length() && PAIRS.contains(source.substring(index, end + 1))) {
                end++;
                kind = Kind.SYMBOL;
            } else if ("+-*/%^!><?:=()[]{},;$".indexOf(c) >= 0)
                kind = Kind.SYMBOL;
            else
                throw new SyntaxIssue(start);
            result.add(new Token(kind, source.substring(index, end), value, start));
            column += end - index;
            index = end;
        }
        result.add(new Token(Kind.END, "", null, new Position(line, 1)));
        return result;
    }
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
public final class Main {
    static final Set<String> SPECIAL =
        Set.of("FILENAME", "FNR", "FS", "NF", "NR", "OFS", "ORS", "SUBSEP");
    record Binding(Parser.Function scope, String name) {}
    record StaticError(Lexer.Position pos, int priority, String message) {}
    static final class StaticIssue extends RuntimeException {
        final Lexer.Position pos;
        StaticIssue(Lexer.Position pos, String message) {
            super(message);
            this.pos = pos;
        }
    }
    static List<Parser.Node> children(Parser.Node node) {
        List<Parser.Node> result = new ArrayList<>();
        switch (node) {
        case Parser.Function f -> {
            result.addAll(f.parameters);
            result.add(f.body);
        }
        case Parser.Rule r -> {
            result.addAll(r.patterns);
            result.add(r.action);
        }
        case Parser.ArrayAccess a -> result.addAll(a.indexes());
        case Parser.Field f -> result.add(f.index());
        case Parser.Paren p -> result.add(p.expression());
        case Parser.Assignment a -> {
            result.add(a.location());
            result.add(a.value());
        }
        case Parser.Increment i -> result.add(i.location());
        case Parser.Conditional c -> {
            result.add(c.condition());
            result.add(c.first());
            result.add(c.second());
        }
        case Parser.Unary u -> result.add(u.operand());
        case Parser.Membership m -> {
            result.addAll(m.indexes());
            result.add(m.array());
        }
        case Parser.Binary b -> {
            result.add(b.left());
            result.add(b.right());
        }
        case Parser.Call c -> result.addAll(c.arguments());
        case Parser.Builtin b -> result.addAll(b.arguments());
        case Parser.Getline g -> {
            result.add(g.target());
            result.add(g.filename());
        }
        case Parser.Block b -> result.addAll(b.statements());
        case Parser.ExpressionStatement e -> result.add(e.expression());
        case Parser.Output o -> {
            result.addAll(o.arguments());
            result.add(o.filename());
        }
        case Parser.If i -> {
            result.add(i.condition());
            result.add(i.first());
            result.add(i.second());
        }
        case Parser.While w -> {
            result.add(w.condition());
            result.add(w.body());
        }
        case Parser.DoWhile d -> {
            result.add(d.body());
            result.add(d.condition());
        }
        case Parser.For f -> {
            result.add(f.initial());
            result.add(f.condition());
            result.add(f.update());
            result.add(f.body());
        }
        case Parser.ForIn f -> {
            result.add(f.variable());
            result.add(f.array());
            result.add(f.body());
        }
        case Parser.Delete d -> {
            result.add(d.array());
            if (d.indexes() != null)
                result.addAll(d.indexes());
        }
        case Parser.TransferStatement t -> result.add(t.value());
        default -> {
        }
        }
        result.removeIf(Objects::isNull);
        return result;
    }
    static final class Analysis {
        final List<Parser.Item> items;
        final List<Parser.Function> functions = new ArrayList<>();
        final List<Parser.Rule> rules = new ArrayList<>();
        final Map<String, Parser.Function> functionTable = new HashMap<>();
        final Set<String> globals = new TreeSet<>(SPECIAL);
        final Set<Binding> bindings = new HashSet<>(), arrays = new HashSet<>();
        final Map<Parser.Node, Binding> resolved = new IdentityHashMap<>();
        final Map<Parser.Call, Parser.Function> targets = new IdentityHashMap<>();
        final Set<Integer> statementLines = new TreeSet<>();
        final List<Parser.Node> nodes = new ArrayList<>();
        final List<StaticError> errors = new ArrayList<>();
        Analysis(List<Parser.Item> items) {
            this.items = items;
            for (String name : SPECIAL)
                bindings.add(new Binding(null, name));
            for (Parser.Item item : items) {
                if (item instanceof Parser.Function f)
                    functions.add(f);
                else
                    rules.add((Parser.Rule)item);
            }
        }
        void error(Lexer.Position pos, int priority, String message) {
            errors.add(new StaticError(pos, priority, message));
        }
        void resolve(Parser.Node node, String name, Parser.Function function) {
            boolean local = function != null && function.parameterNames.contains(name);
            Binding binding = new Binding(local ? function : null, name);
            resolved.put(node, binding);
            bindings.add(binding);
            if (!local)
                globals.add(name);
            if (functionTable.containsKey(name))
                error(node.pos(), 2, "function " + name + " used as variable");
        }
        void collect(Parser.Node node, Parser.Function function) {
            nodes.add(node);
            if (node instanceof Parser.Stmt && !(node instanceof Parser.Block) &&
                !(node instanceof Parser.Empty))
                statementLines.add(node.pos().line());
            if (node instanceof Parser.Variable v)
                resolve(v, v.name(), function);
            else if (node instanceof Parser.ArrayAccess a)
                resolve(a, a.name(), function);
            else if (node instanceof Parser.Call call) {
                Parser.Function target = functionTable.get(call.name());
                if (target == null)
                    error(call.pos(), 3, "undefined function " + call.name());
                else {
                    targets.put(call, target);
                    if (call.arguments().size() > target.parameters.size())
                        error(call.pos(), 4, "too many arguments to " + call.name());
                }
            }
            for (Parser.Node child : children(node))
                collect(child, function);
        }
        Binding root(Map<Binding, Binding> parents, Binding binding) {
            Binding parent = parents.get(binding);
            if (!parent.equals(binding)) {
                parent = root(parents, parent);
                parents.put(binding, parent);
            }
            return parent;
        }
        Analysis prepare() {
            for (Parser.Function function : functions) {
                if (functionTable.putIfAbsent(function.name, function) != null)
                    error(function.namePos, 0, "function " + function.name + " redefined");
                for (Parser.Variable parameter : function.parameters)
                    if (!function.parameterNames.add(parameter.name()))
                        error(parameter.pos(), 1, "duplicate parameter " + parameter.name());
            }
            for (Parser.Item item : items)
                collect(item, item instanceof Parser.Function f ? f : null);
            if (!errors.isEmpty()) {
                errors.sort(Comparator.comparing(StaticError::pos)
                                .thenComparingInt(StaticError::priority)
                                .thenComparing(StaticError::message));
                StaticError first = errors.getFirst();
                throw new StaticIssue(first.pos(), first.message());
            }
            Map<Binding, Binding> parents = new HashMap<>();
            for (Binding binding : bindings)
                parents.put(binding, binding);
            for (Parser.Node node : nodes) {
                if (node instanceof Parser.ArrayAccess)
                    arrays.add(resolved.get(node));
                else if (node instanceof Parser.Membership m)
                    arrays.add(resolved.get(m.array()));
                else if (node instanceof Parser.Delete d)
                    arrays.add(resolved.get(d.array()));
                else if (node instanceof Parser.ForIn f)
                    arrays.add(resolved.get(f.array()));
                else if (node instanceof Parser.Builtin b && b.name().equals("split"))
                    arrays.add(resolved.get(b.arguments().get(1)));
                else if (node instanceof Parser.Call call) {
                    Parser.Function target = targets.get(call);
                    for (int i = 0; i < call.arguments().size(); i++)
                        if (call.arguments().get(i) instanceof Parser.Variable variable)
                            parents.put(root(parents, resolved.get(variable)),
                                        root(parents, resolved.get(target.parameters.get(i))));
                }
            }
            Set<Binding> arrayRoots = new HashSet<>();
            for (Binding binding : arrays)
                arrayRoots.add(root(parents, binding));
            arrays.clear();
            for (Binding binding : bindings)
                if (arrayRoots.contains(root(parents, binding)))
                    arrays.add(binding);
            return this;
        }
    }
    static ValuesFields.Value number(int value) { return ValuesFields.number(value); }
    static ValuesFields.Value string(String text) { return ValuesFields.string(text); }
    static int numeric(ValuesFields.Value value) { return ValuesFields.numeric(value); }
    static String text(ValuesFields.Value value) { return ValuesFields.text(value); }
    static boolean truth(ValuesFields.Value value) { return ValuesFields.truth(value); }
    static ValuesFields.Value arithmetic(String operator, ValuesFields.Value first,
                                         ValuesFields.Value second, Lexer.Position pos) {
        int a = numeric(first), b = numeric(second);
        return number(switch (operator) {
            case "/", "%" -> {
                if (b == 0)
                    throw new Builtins.RuntimeIssue(pos, "division by zero");
                yield operator.equals("/") ? a / b : a % b;
            }
            case "^" -> {
                if (b < 0)
                    throw new Builtins.RuntimeIssue(pos, "negative exponent");
                int result = 1, base = a, power = b;
                while (power > 0) {
                    if ((power & 1) != 0)
                        result *= base;
                    power >>= 1;
                    if (power > 0)
                        base *= base;
                }
                yield result;
            }
            case "+" -> a + b;
            case "-" -> a - b;
            default -> a *b;
        });
    }
    enum Flow { NEXT, BREAK, CONTINUE, EXIT, RETURN }
    static final class Transfer extends RuntimeException {
        final Flow flow;
        final ValuesFields.Value value;
        Transfer(Flow flow) { this(flow, ValuesFields.UNINITIALIZED); }
        Transfer(Flow flow, ValuesFields.Value value) {
            this.flow = flow;
            this.value = value;
        }
    }
    static final class Cell {
        ValuesFields.Value scalar = ValuesFields.UNINITIALIZED;
        final Map<String, ValuesFields.Value> array;
        Cell(boolean array) { this.array = array ? new HashMap<>() : null; }
        Cell(ValuesFields.Value value) {
            scalar = value;
            array = null;
        }
    }
    sealed interface Location permits VariableLocation, ArrayLocation, FieldLocation {}
    record VariableLocation(Binding binding) implements Location {}
    record ArrayLocation(Map<String, ValuesFields.Value> array, String key) implements Location {}
    record FieldLocation(int index) implements Location {}
    static final class Engine {
        final Analysis analysis;
        final Streams.Arguments arguments;
        final Set<String> globalNames;
        final Map<String, Cell> globals = new HashMap<>();
        final Deque<Map<String, Cell>> locals = new ArrayDeque<>();
        final ValuesFields.Record record;
        final Streams streams = new Streams();
        final TreeMap<Integer, Integer> lines = new TreeMap<>();
        String phase = "BEGIN";
        int exitStatus, operandIndex, inputIndex;
        Streams.Operand current;
        List<String> inputLines = List.of();
        Builtins.RuntimeIssue error;
        Engine(Analysis analysis, Streams.Arguments arguments) {
            this.analysis = analysis;
            this.arguments = arguments;
            globalNames = new TreeSet<>(analysis.globals);
            for (String name : globalNames)
                globals.put(name, new Cell(analysis.arrays.contains(new Binding(null, name))));
            for (String name : List.of("NR", "FNR", "NF"))
                globals.put(name, new Cell(number(0)));
            globals.put("FILENAME", new Cell(string("")));
            globals.put("FS", new Cell(string(" ")));
            globals.put("OFS", new Cell(string(" ")));
            globals.put("ORS", new Cell(string("\n")));
            globals.put("SUBSEP", new Cell(string(String.valueOf((char)28))));
            record
            = new ValuesFields.Record(this::global);
            for (int line : analysis.statementLines)
                lines.put(line, 0);
        }
        Cell cell(Binding binding) {
            return binding.scope() == null ? globals.get(binding.name())
                                           : locals.peek().get(binding.name());
        }
        ValuesFields.Value variable(Binding binding) {
            return binding.scope() == null && binding.name().equals("NF")
                ? number(record.fields.size())
                : cell(binding).scalar;
        }
        ValuesFields.Value global(String name) { return variable(new Binding(null, name)); }
        Map<String, ValuesFields.Value> array(Parser.Node node) {
            return cell(analysis.resolved.get(node)).array;
        }
        void assignInput(String name, String text) {
            globalNames.add(name);
            globals.put(name, new Cell(ValuesFields.input(text)));
        }
        String subscript(List<Parser.Expr> expressions) throws IOException {
            List<String> values = new ArrayList<>();
            for (Parser.Expr expression : expressions)
                values.add(text(evaluate(expression)));
            return String.join(text(global("SUBSEP")), values);
        }
        Location location(Parser.Expr node) throws IOException {
            if (node instanceof Parser.Variable)
                return new VariableLocation(analysis.resolved.get(node));
            if (node instanceof Parser.ArrayAccess access) {
                String key = subscript(access.indexes());
                return new ArrayLocation(array(access), key);
            }
            Parser.Field field = (Parser.Field)node;
            int index = numeric(evaluate(field.index()));
            if (index < 0)
                throw new Builtins.RuntimeIssue(field.pos(), "negative field index");
            return new FieldLocation(index);
        }
        ValuesFields.Value read(Location location) {
            return switch (location) {
                case VariableLocation v -> variable(v.binding());
                case FieldLocation f -> record.read(f.index()) ;
                case ArrayLocation a ->
                    a.array().computeIfAbsent(a.key(), key -> ValuesFields.UNINITIALIZED);
            };
        }
        void store(Location location, ValuesFields.Value value, Lexer.Position pos) {
            switch (location) {
            case FieldLocation f -> record.write(f.index(), value) ;
            case ArrayLocation a -> a.array().put(a.key(), value);
            case VariableLocation v -> {
                Binding binding = v.binding();
                if (binding.scope() == null && binding.name().equals("NF")) {
                    int size = numeric(value);
                    if (size < 0)
                        throw new Builtins.RuntimeIssue(pos, "negative NF");
                    record.resize(size)
                    ;
                } else
                    cell(binding).scalar = value;
            }
            }
        }
        ValuesFields.Value evaluate(Parser.Expr expression) throws IOException {
            return switch (expression) {
                case Parser.Literal literal -> literal.value();
                case Parser.Variable v -> read(location(v));
                case Parser.ArrayAccess a -> read(location(a));
                case Parser.Field f -> read(location(f));
                case Parser.Paren p -> evaluate(p.expression());
                case Parser.Assignment a -> {
                    Location location = location(a.location());
                    ValuesFields.Value value = evaluate(a.value());
                    if (!a.operator().equals("="))
                        value = arithmetic(a.operator().substring(0, 1), read(location), value,
                                           a.pos());
                    store(location, value, a.pos());
                    yield read(location);
                }
                case Parser.Increment i -> {
                    Location location = location(i.location());
                    int old = numeric(read(location)), value = old + i.delta();
                    store(location, number(value), i.pos());
                    yield number(i.prefix() ? value : old);
                }
                case Parser.Conditional c ->
                    evaluate(truth(evaluate(c.condition())) ? c.first() : c.second());
                case Parser.Unary u -> {
                    ValuesFields.Value value = evaluate(u.operand());
                    yield number(u.operator().equals("!")   ? (truth(value) ? 0 : 1)
                                 : u.operator().equals("-") ? -numeric(value)
                                                            : numeric(value));
                }
                case Parser.Membership m -> {
                    String key = subscript(m.indexes());
                    yield number(array(m.array()).containsKey(key) ? 1 : 0);
                }
                case Parser.Binary binary -> binary(binary);
                case Parser.Call call -> call(call);
                case Parser.Builtin builtin -> builtin(builtin);
                case Parser.Getline getline -> getline(getline);
            };
        }
        ValuesFields.Value binary(Parser.Binary binary) throws IOException {
            ValuesFields.Value first = evaluate(binary.left());
            String operator = binary.operator();
            if (operator.equals("||") && truth(first))
                return number(1);
            if (operator.equals("&&") && !truth(first))
                return number(0);
            ValuesFields.Value second = evaluate(binary.right());
            if (operator.equals("&&") || operator.equals("||"))
                return number(truth(second) ? 1 : 0);
            if (operator.equals("concat"))
                return string(text(first) + text(second));
            if (Parser.COMPARISONS.contains(operator)) {
                int order = ValuesFields.compare(first, second);
                return number((switch (operator) {
                    case "<" -> order < 0;
                    case "<=" -> order <= 0;
                    case "==" -> order == 0;
                    case "!=" -> order != 0;
                    case ">=" -> order >= 0;
                    default -> order > 0;
                })
                                  ? 1
                                  : 0);
            }
            return arithmetic(operator, first, second, binary.pos());
        }
        ValuesFields.Value call(Parser.Call call) throws IOException {
            Parser.Function function = analysis.targets.get(call);
            Map<String, Cell> local = new HashMap<>();
            for (int i = 0; i < function.parameters.size(); i++) {
                Parser.Variable parameter = function.parameters.get(i);
                boolean isArray = analysis.arrays.contains(analysis.resolved.get(parameter));
                Cell value;
                if (i < call.arguments().size()) {
                    Parser.Expr argument = call.arguments().get(i);
                    if (isArray)
                        value = cell(analysis.resolved.get(argument));
                    else
                        value = new Cell(evaluate(argument));
                } else
                    value = new Cell(isArray);
                local.put(parameter.name(), value);
            }
            function.calls++;
            function.active++;
            function.depth = Math.max(function.depth, function.active);
            locals.push(local);
            try {
                statement(function.body);
            } catch (Transfer transfer) {
                if (transfer.flow == Flow.RETURN)
                    return transfer.value;
                throw transfer;
            } finally {
                locals.pop();
                function.active--;
            }
            return ValuesFields.UNINITIALIZED;
        }
        ValuesFields.Value builtin(Parser.Builtin builtin) throws IOException {
            List<Parser.Expr> args = builtin.arguments();
            String name = builtin.name();
            if (name.equals("length")) {
                if (args.isEmpty())
                    return number(text(record.zero).length());
                Parser.Expr argument = args.getFirst();
                if (argument instanceof Parser.Variable &&
                    analysis.arrays.contains(analysis.resolved.get(argument)))
                    return number(array(argument).size());
                return number(text(evaluate(argument)).length());
            }
            if (name.equals("split")) {
                String text = text(evaluate(args.getFirst()));
                String separator =
                    args.size() == 3 ? text(evaluate(args.get(2))) : text(global("FS"));
                Map<String, ValuesFields.Value> array = array(args.get(1));
                array.clear();
                List<String> pieces = ValuesFields.split(text, separator);
                for (int i = 0; i < pieces.size(); i++)
                    array.put(Integer.toString(i + 1), ValuesFields.input(pieces.get(i)));
                return number(pieces.size());
            }
            if (name.equals("close"))
                return number(streams.close(text(evaluate(args.getFirst()))));
            List<ValuesFields.Value> values = new ArrayList<>();
            for (Parser.Expr argument : args)
                values.add(evaluate(argument));
            return Builtins.invoke(name, values, builtin.pos());
        }
        ValuesFields.Value getline(Parser.Getline getline) throws IOException {
            Streams.Read result;
            if (getline.filename() != null)
                result = streams.getline(text(evaluate(getline.filename())));
            else if (phase.equals("END"))
                return number(0);
            else {
                String line = nextRecord();
                result = new Streams.Read(line == null ? 0 : 1, line);
            }
            if (result.status() == 1) {
                if (getline.target() == null)
                    record.set(result.line())
                ;
                else {
                    Location location = location(getline.target());
                    store(location, ValuesFields.input(result.line()), getline.pos());
                }
            }
            return number(result.status());
        }
        void output(Parser.Output output) throws IOException {
            List<ValuesFields.Value> values = new ArrayList<>();
            for (Parser.Expr expression : output.arguments())
                values.add(evaluate(expression));
            String content;
            if (output.formatted())
                content = Builtins.format(values, output.pos());
            else {
                if (values.isEmpty())
                    values.add(record.zero);
                StringJoiner joined = new StringJoiner(text(global("OFS")));
                for (ValuesFields.Value value : values)
                    joined.add(text(value));
                content = joined + text(global("ORS"));
            }
            String filename = output.filename() == null ? null : text(evaluate(output.filename()));
            streams.write(content, filename, output.redirect(), output.redirectPos());
        }
        boolean loopBody(Parser.Stmt body) throws IOException {
            try {
                statement(body);
            } catch (Transfer transfer) {
                if (transfer.flow == Flow.BREAK)
                    return false;
                if (transfer.flow != Flow.CONTINUE)
                    throw transfer;
            }
            return true;
        }
        void statement(Parser.Stmt statement) throws IOException {
            if (statement instanceof Parser.Block block) {
                for (Parser.Stmt child : block.statements())
                    statement(child);
                return;
            }
            if (statement instanceof Parser.Empty)
                return;
            lines.merge(statement.pos().line(), 1, Integer::sum);
            switch (statement) {
            case Parser.ExpressionStatement expression -> evaluate(expression.expression());
            case Parser.Output output -> output(output);
            case Parser.If branch -> {
                Parser.Stmt selected =
                    truth(evaluate(branch.condition())) ? branch.first() : branch.second();
                if (selected != null)
                    statement(selected);
            }
            case Parser.While loop -> {
                while (truth(evaluate(loop.condition())))
                    if (!loopBody(loop.body()))
                        break;
            }
            case Parser.DoWhile loop -> {
                do {
                    if (!loopBody(loop.body()))
                        break;
                } while (truth(evaluate(loop.condition())));
            }
            case Parser.For loop -> {
                if (loop.initial() != null)
                    evaluate(loop.initial());
                while (loop.condition() == null || truth(evaluate(loop.condition()))) {
                    if (!loopBody(loop.body()))
                        break;
                    if (loop.update() != null)
                        evaluate(loop.update());
                }
            }
            case Parser.ForIn loop -> {
                List<String> keys = new ArrayList<>(array(loop.array()).keySet());
                keys.sort(ValuesFields.KEY_ORDER);
                for (String key : keys) {
                    store(new VariableLocation(analysis.resolved.get(loop.variable())),
                          ValuesFields.input(key), loop.variable().pos());
                    if (!loopBody(loop.body()))
                        break;
                }
            }
            case Parser.Delete delete -> {
                Map<String, ValuesFields.Value> array = array(delete.array());
                if (delete.indexes() == null)
                    array.clear();
                else
                    array.remove(subscript(delete.indexes()));
            }
            case Parser.TransferStatement transfer -> {
                switch (transfer.kind()) {
                case "next" -> {
                    if (phase.equals("BEGIN") || phase.equals("END"))
                        throw new Builtins.RuntimeIssue(transfer.pos(),
                                                        "next used in BEGIN or END");
                    throw new Transfer(Flow.NEXT);
                }
                case "exit" -> {
                    if (transfer.value() != null)
                        exitStatus = numeric(evaluate(transfer.value()));
                    throw new Transfer(Flow.EXIT);
                }
                case "return" ->
                    throw new Transfer(Flow.RETURN, transfer.value() == null
                                                        ? ValuesFields.UNINITIALIZED
                                                        : evaluate(transfer.value()));
                case "break" -> throw new Transfer(Flow.BREAK);
                default -> throw new Transfer(Flow.CONTINUE);
                }
            }
            default -> throw new AssertionError();
            }
        }
        String nextRecord() throws IOException {
            while (true) {
                if (inputIndex < inputLines.size()) {
                    String line = inputLines.get(inputIndex++);
                    current.records++;
                    globals.get("NR").scalar = number(numeric(global("NR")) + 1);
                    globals.get("FNR").scalar = number(numeric(global("FNR")) + 1);
                    return line;
                }
                if (operandIndex == arguments.operands().size())
                    return null;
                Streams.Operand operand = arguments.operands().get(operandIndex++);
                if (!operand.file)
                    assignInput(operand.name, operand.value);
                else {
                    current = operand;
                    inputLines = Streams.records(operand.name);
                    inputIndex = 0;
                    globals.get("FILENAME").scalar = string(operand.name);
                    globals.get("FNR").scalar = number(0);
                }
            }
        }
        void actions(String phase) throws IOException {
            this.phase = phase;
            for (Parser.Rule rule : analysis.rules)
                if (rule.flavor.equals(phase)) {
                    rule.count++;
                    statement(rule.action);
                }
        }
        boolean matches(Parser.Rule rule) throws IOException {
            if (rule.flavor.equals("all"))
                return true;
            if (rule.flavor.equals("pattern"))
                return truth(evaluate(rule.patterns.getFirst()));
            if (!rule.inside && truth(evaluate(rule.patterns.getFirst())))
                rule.inside = true;
            if (!rule.inside)
                return false;
            if (truth(evaluate(rule.patterns.get(1))))
                rule.inside = false;
            return true;
        }
        void records() throws IOException {
            if (analysis.rules.stream().noneMatch(rule -> !rule.flavor.equals("BEGIN")))
                return;
            phase = "records";
            String line;
            while ((line = nextRecord()) != null) {
                record.set(line)
                ;
                try {
                    for (Parser.Rule rule : analysis.rules)
                        if (!rule.flavor.equals("BEGIN") && !rule.flavor.equals("END") &&
                            matches(rule)) {
                            rule.count++;
                            if (rule.action == null)
                                streams.write(text(record.zero) + text(global("ORS")), null, null,
                                              null);
                            else
                                statement(rule.action);
                        }
                } catch (Transfer transfer) {
                    if (transfer.flow != Flow.NEXT)
                        throw transfer;
                }
            }
        }
        void execute() throws IOException {
            try {
                for (Streams.Option option : arguments.options())
                    assignInput(option.name(), option.value());
                try {
                    actions("BEGIN");
                    records();
                } catch (Transfer transfer) {
                    if (transfer.flow != Flow.EXIT)
                        throw transfer;
                }
                try {
                    actions("END");
                } catch (Transfer transfer) {
                    if (transfer.flow != Flow.EXIT)
                        throw transfer;
                }
            } catch (Builtins.RuntimeIssue issue) {
                error = issue;
            }
        }
        List<String> statistics() {
            List<String> result = new ArrayList<>();
            result.add(error == null
                           ? "status: exit " + exitStatus
                           : "status: runtime error at " + error.pos + ": " + error.getMessage());
            result.add("[inputs]");
            for (Streams.Operand operand : arguments.operands())
                if (operand.file)
                    result.add(operand.name + " records=" + operand.records);
            result.add("[getline]");
            for (var entry : streams.inputs.entrySet())
                result.add(
                    entry.getKey() + " " +
                    (entry.getValue().everOpened ? "reads=" + entry.getValue().reads : "missing"));
            result.add("[rules]");
            for (Parser.Rule rule : analysis.rules)
                result.add(rule.pos + " " + rule.flavor + " count=" + rule.count);
            result.add("[functions]");
            for (Parser.Function function : analysis.functions)
                result.add(function.name + " calls=" + function.calls + " depth=" + function.depth);
            result.add("[outputs]");
            result.add("stdout.txt writes=" + streams.stdout.writes +
                       " bytes=" + streams.stdout.content.length());
            for (var entry : streams.outputs.entrySet())
                result.add(entry.getKey() + " writes=" + entry.getValue().writes +
                           " bytes=" + entry.getValue().content.length());
            result.add("[lines]");
            for (var entry : lines.entrySet())
                result.add(entry.getKey() + " count=" + entry.getValue());
            result.add("[globals]");
            for (String name : globalNames) {
                Binding binding = new Binding(null, name);
                result.add(name + " = " +
                           (analysis.arrays.contains(binding)
                                ? "array (" + globals.get(name).array.size() + ")"
                                : ValuesFields.describe(variable(binding))));
            }
            return result;
        }
    }
    public static void main(String[] args) throws IOException {
        Streams.Arguments arguments =
            Streams.parse(Files.readString(Path.of("input/args.txt"), StandardCharsets.US_ASCII));
        String source = Files.readString(Path.of("input/program.awk"), StandardCharsets.US_ASCII);
        Streams streams;
        List<String> statistics;
        try {
            Analysis analysis = new Analysis(new Parser(Lexer.tokenize(source)).parse()).prepare();
            Engine engine = new Engine(analysis, arguments);
            engine.execute();
            streams = engine.streams;
            statistics = engine.statistics();
        } catch (Lexer.SyntaxIssue issue) {
            streams = new Streams();
            statistics = List.of("status: syntax error at " + issue.pos);
        } catch (StaticIssue issue) {
            streams = new Streams();
            statistics = List.of("status: error at " + issue.pos + ": " + issue.getMessage());
        }
        streams.save();
        Files.writeString(Path.of("output/stats.txt"), String.join("\n", statistics) + "\n",
                          StandardCharsets.US_ASCII);
    }
}

import java.util.*;
final class Parser {
    interface Node {
        Lexer.Position pos();
    }
    sealed interface Expr extends Node permits Variable, ArrayAccess, Field, Literal, Paren,
                                  Assignment, Increment, Conditional, Unary, Membership, Binary,
                                  Call, Builtin, Getline {}
    sealed interface Stmt extends Node permits Block, Empty, ExpressionStatement, Output, If, While,
                                  DoWhile, For, ForIn, Delete, TransferStatement {}
    sealed interface Item extends Node permits Function, Rule {}
    record Variable(String name, Lexer.Position pos) implements Expr {}
    record ArrayAccess(String name, List<Expr> indexes, Lexer.Position pos) implements Expr {}
    record Field(Expr index, Lexer.Position pos) implements Expr {}
    record Literal(ValuesFields.Value value, Lexer.Position pos) implements Expr {}
    record Paren(Expr expression, Lexer.Position pos) implements Expr {}
    record Assignment(String operator, Expr location, Expr value, Lexer.Position pos)
        implements Expr {}
    record Increment(Expr location, int delta, boolean prefix, Lexer.Position pos) implements Expr {
    }
    record Conditional(Expr condition, Expr first, Expr second, Lexer.Position pos)
        implements Expr {}
    record Unary(String operator, Expr operand, Lexer.Position pos) implements Expr {}
    record Membership(List<Expr> indexes, Variable array, Lexer.Position pos) implements Expr {}
    record Binary(String operator, Expr left, Expr right, Lexer.Position pos) implements Expr {}
    record Call(String name, List<Expr> arguments, Lexer.Position pos) implements Expr {}
    record Builtin(String name, List<Expr> arguments, Lexer.Position pos) implements Expr {}
    record Getline(Expr target, Expr filename, Lexer.Position pos) implements Expr {}
    record Block(List<Stmt> statements, Lexer.Position pos) implements Stmt {}
    record Empty(Lexer.Position pos) implements Stmt {}
    record ExpressionStatement(Expr expression, Lexer.Position pos) implements Stmt {}
    record Output(boolean formatted, List<Expr> arguments, String redirect,
                  Lexer.Position redirectPos, Expr filename, Lexer.Position pos) implements Stmt {}
    record If(Expr condition, Stmt first, Stmt second, Lexer.Position pos) implements Stmt {}
    record While(Expr condition, Stmt body, Lexer.Position pos) implements Stmt {}
    record DoWhile(Stmt body, Expr condition, Lexer.Position pos) implements Stmt {}
    record For(Expr initial, Expr condition, Expr update, Stmt body, Lexer.Position pos)
        implements Stmt {}
    record ForIn(Variable variable, Variable array, Stmt body, Lexer.Position pos) implements Stmt {
    }
    record Delete(Variable array, List<Expr> indexes, Lexer.Position pos) implements Stmt {}
    record TransferStatement(String kind, Expr value, Lexer.Position pos) implements Stmt {}
    static final class Function implements Item {
        final String name;
        final Lexer.Position pos, namePos;
        final List<Variable> parameters;
        final Block body;
        final Set<String> parameterNames = new HashSet<>();
        int calls, active, depth;
        Function(String name, Lexer.Position pos, Lexer.Position namePos, List<Variable> parameters,
                 Block body) {
            this.name = name;
            this.pos = pos;
            this.namePos = namePos;
            this.parameters = parameters;
            this.body = body;
        }
        public Lexer.Position pos() { return pos; }
    }
    static final class Rule implements Item {
        final String flavor;
        final Lexer.Position pos;
        final List<Expr> patterns;
        final Block action;
        int count;
        boolean inside;
        Rule(String flavor, Lexer.Position pos, List<Expr> patterns, Block action) {
            this.flavor = flavor;
            this.pos = pos;
            this.patterns = patterns;
            this.action = action;
        }
        public Lexer.Position pos() { return pos; }
    }
    static final Set<String> ASSIGNMENTS = Set.of("=", "+=", "-=", "*=", "/=", "%=", "^="),
                             COMPARISONS = Set.of("<", "<=", "==", "!=", ">=", ">");
    final List<Lexer.Token> tokens;
    int index, loopDepth;
    boolean function;
    String phase;
    Parser(List<Lexer.Token> tokens) { this.tokens = tokens; }
    Lexer.Token peek() { return tokens.get(index); }
    Lexer.Token take() { return tokens.get(index++); }
    boolean at(String text) { return peek().text().equals(text); }
    Lexer.Token accept(String text) { return at(text) ? take() : null; }
    Lexer.Token expect(String text) {
        if (!at(text))
            fail();
        return take();
    }
    void fail() { throw new Lexer.SyntaxIssue(peek().pos()); }
    void fail(Lexer.Position pos) { throw new Lexer.SyntaxIssue(pos); }
    Variable name() {
        if (peek().kind() != Lexer.Kind.NAME)
            fail();
        Lexer.Token token = take();
        return new Variable(token.text(), token.pos());
    }
    void newlines() {
        while (accept("\n") != null) {
        }
    }
    List<Item> parse() {
        List<Item> items = new ArrayList<>();
        while (peek().kind() != Lexer.Kind.END) {
            if (at("\n") || at(";")) {
                take();
                continue;
            }
            Lexer.Token start = peek();
            if (accept("function") != null) {
                if (peek().kind() != Lexer.Kind.NAME && peek().kind() != Lexer.Kind.FUNCNAME)
                    fail();
                Lexer.Token name = take();
                expect("(");
                List<Variable> parameters = new ArrayList<>();
                if (!at(")")) {
                    while (true) {
                        parameters.add(name());
                        if (accept(",") == null)
                            break;
                        newlines();
                    }
                }
                expect(")");
                newlines();
                function = true;
                Block body = block();
                function = false;
                items.add(new Function(name.text(), start.pos(), name.pos(), parameters, body));
                continue;
            }
            List<Expr> patterns = new ArrayList<>();
            String flavor;
            if (at("BEGIN") || at("END"))
                flavor = take().text();
            else if (at("{"))
                flavor = "all";
            else {
                patterns.add(expression());
                if (accept(",") != null) {
                    newlines();
                    patterns.add(expression());
                }
                flavor = patterns.size() == 2 ? "range" : "pattern";
            }
            phase = flavor;
            Block action = null;
            if (flavor.equals("BEGIN") || flavor.equals("END") || flavor.equals("all") || at("{"))
                action = block();
            else if (!at("\n") && !at(";") && peek().kind() != Lexer.Kind.END)
                fail();
            phase = null;
            items.add(new Rule(flavor, start.pos(), patterns, action));
        }
        return items;
    }
    Block block() {
        Lexer.Token opening = expect("{");
        List<Stmt> statements = new ArrayList<>();
        while (!at("}")) {
            if (at("\n") || at(";"))
                take();
            else
                statements.add(statement());
        }
        expect("}");
        return new Block(statements, opening.pos());
    }
    Expr condition() {
        expect("(");
        Expr value = expression();
        expect(")");
        return value;
    }
    Stmt loopBody() {
        newlines();
        loopDepth++;
        Stmt body = statement();
        loopDepth--;
        return body;
    }
    void terminator() {
        if (at(";") || at("\n"))
            take();
        else if (!at("}"))
            fail();
    }
    Stmt statement() {
        Lexer.Token token = peek();
        String spelling = token.text();
        if (at("{"))
            return block();
        if (accept(";") != null)
            return new Empty(token.pos());
        if (accept("if") != null) {
            Expr condition = condition();
            newlines();
            Stmt first = statement();
            newlines();
            Stmt second = null;
            if (accept("else") != null) {
                newlines();
                second = statement();
            }
            return new If(condition, first, second, token.pos());
        }
        if (accept("while") != null) {
            Expr condition = condition();
            return new While(condition, loopBody(), token.pos());
        }
        if (accept("do") != null) {
            Stmt body = loopBody();
            newlines();
            expect("while");
            Expr condition = condition();
            terminator();
            return new DoWhile(body, condition, token.pos());
        }
        if (accept("for") != null) {
            expect("(");
            if (index + 3 < tokens.size() && peek().kind() == Lexer.Kind.NAME &&
                tokens.get(index + 1).text().equals("in") &&
                tokens.get(index + 2).kind() == Lexer.Kind.NAME &&
                tokens.get(index + 3).text().equals(")")) {
                Variable variable = name();
                expect("in");
                Variable array = name();
                expect(")");
                return new ForIn(variable, array, loopBody(), token.pos());
            }
            Expr initial = at(";") ? null : expression();
            expect(";");
            newlines();
            Expr condition = at(";") ? null : expression();
            expect(";");
            newlines();
            Expr update = at(")") ? null : expression();
            expect(")");
            return new For(initial, condition, update, loopBody(), token.pos());
        }
        Stmt result;
        if (spelling.equals("print") || spelling.equals("printf")) {
            take();
            result = output(token);
        } else if (accept("delete") != null) {
            Variable array = name();
            List<Expr> indexes = null;
            if (accept("[") != null) {
                indexes = expressionList(true);
                expect("]");
            }
            result = new Delete(array, indexes, token.pos());
        } else if (Set.of("next", "break", "continue", "exit", "return").contains(spelling)) {
            take();
            if (spelling.equals("next") && !function &&
                (Objects.equals(phase, "BEGIN") || Objects.equals(phase, "END")))
                fail(token.pos());
            if (spelling.equals("return") && !function)
                fail(token.pos());
            if ((spelling.equals("break") || spelling.equals("continue")) && loopDepth == 0)
                fail(token.pos());
            Expr value = null;
            if ((spelling.equals("exit") || spelling.equals("return")) && !at(";") && !at("\n") &&
                !at("}"))
                value = expression();
            result = new TransferStatement(spelling, value, token.pos());
        } else
            result = new ExpressionStatement(expression(), token.pos());
        terminator();
        return result;
    }
    boolean parenthesizedOutput() {
        if (!at("("))
            return false;
        int depth = 0;
        for (int i = index; i < tokens.size(); i++) {
            String spelling = tokens.get(i).text();
            if (spelling.equals("("))
                depth++;
            else if (spelling.equals(")") && --depth == 0) {
                Lexer.Token next = tokens.get(i + 1);
                return Set.of(";", "\n", "}", ">", ">>").contains(next.text()) ||
                    next.kind() == Lexer.Kind.END;
            }
        }
        return false;
    }
    Output output(Lexer.Token token) {
        List<Expr> arguments = new ArrayList<>();
        if (parenthesizedOutput()) {
            expect("(");
            arguments = expressionList(true);
            expect(")");
        } else if (!Set.of(";", "\n", "}", ">", ">>").contains(peek().text()))
            arguments = expressionList(false);
        if (token.text().equals("printf") && arguments.isEmpty())
            fail();
        Lexer.Token redirect = at(">") || at(">>") ? take() : null;
        Expr filename = redirect == null ? null : concatenation();
        return new Output(token.text().equals("printf"), arguments,
                          redirect == null ? null : redirect.text(),
                          redirect == null ? null : redirect.pos(), filename, token.pos());
    }
    List<Expr> expressionList(boolean greater) {
        List<Expr> result = new ArrayList<>();
        result.add(expression(greater));
        while (accept(",") != null) {
            newlines();
            result.add(expression(greater));
        }
        return result;
    }
    Expr expression() { return expression(true); }
    Expr expression(boolean greater) {
        Expr left = conditional(greater);
        if (lvalue(left) && ASSIGNMENTS.contains(peek().text())) {
            Lexer.Token operator = take();
            return new Assignment(operator.text(), left, expression(greater), operator.pos());
        }
        return left;
    }
    static boolean lvalue(Expr expr) {
        return expr instanceof Variable || expr instanceof ArrayAccess || expr instanceof Field;
    }
    Expr conditional(boolean greater) {
        Expr condition = logical(0, greater);
        Lexer.Token operator = accept("?");
        if (operator == null)
            return condition;
        Expr first = conditional(greater);
        expect(":");
        return new Conditional(condition, first, conditional(greater), operator.pos());
    }
    Expr binary(Lexer.Token operator, Expr left, Expr right) {
        return new Binary(operator.text(), left, right, operator.pos());
    }
    Expr logical(int level, boolean greater) {
        if (level == 2)
            return membership(greater);
        String operatorName = level == 0 ? "||" : "&&";
        Expr left = logical(level + 1, greater);
        while (at(operatorName)) {
            Lexer.Token operator = take();
            newlines();
            left = binary(operator, left, logical(level + 1, greater));
        }
        return left;
    }
    Expr membership(boolean greater) {
        Expr left = comparison(greater);
        while (at("in")) {
            Lexer.Token operator = take();
            left = new Membership(List.of(left), name(), operator.pos());
        }
        return left;
    }
    Expr comparison(boolean greater) {
        Expr left = concatenation();
        while (COMPARISONS.contains(peek().text()) && (greater || !at(">"))) {
            Lexer.Token operator = take();
            left = binary(operator, left, concatenation());
        }
        return left;
    }
    Expr concatenation() {
        Expr left = additive();
        while (Set.of(Lexer.Kind.NUMBER, Lexer.Kind.STRING, Lexer.Kind.NAME, Lexer.Kind.FUNCNAME,
                      Lexer.Kind.BUILTIN)
                   .contains(peek().kind()) ||
               Set.of("$", "(", "++", "--").contains(peek().text())) {
            Lexer.Position pos = peek().pos();
            left = new Binary("concat", left, additive(), pos);
        }
        return left;
    }
    Expr additive() {
        Expr left = multiplicative();
        while (at("+") || at("-")) {
            Lexer.Token operator = take();
            left = binary(operator, left, multiplicative());
        }
        return left;
    }
    Expr multiplicative() {
        Expr left = unary();
        while (at("*") || at("/") || at("%")) {
            Lexer.Token operator = take();
            left = binary(operator, left, unary());
        }
        return left;
    }
    Expr unary() {
        if (at("!") || at("-") || at("+")) {
            Lexer.Token operator = take();
            return new Unary(operator.text(), unary(), operator.pos());
        }
        Expr left = postfix();
        if (at("^")) {
            Lexer.Token operator = take();
            left = binary(operator, left, unary());
        }
        return left;
    }
    Expr prefix() {
        Lexer.Token operator = take();
        return new Increment(lvalue(), operator.text().equals("++") ? 1 : -1, true, operator.pos());
    }
    Expr postfix() {
        if (at("++") || at("--"))
            return prefix();
        Expr left = atom();
        if (lvalue(left) && (at("++") || at("--"))) {
            Lexer.Token operator = take();
            return new Increment(left, operator.text().equals("++") ? 1 : -1, false,
                                 operator.pos());
        }
        return left;
    }
    Expr lvalue() {
        if (peek().kind() == Lexer.Kind.NAME) {
            Variable node = name();
            if (accept("[") != null) {
                List<Expr> indexes = expressionList(true);
                expect("]");
                return new ArrayAccess(node.name(), indexes, node.pos());
            }
            return node;
        }
        Lexer.Token dollar = accept("$");
        if (dollar != null)
            return new Field(at("++") || at("--") ? prefix() : atom(), dollar.pos());
        fail();
        throw new AssertionError();
    }
    Expr atom() {
        Lexer.Token token = peek();
        if (token.kind() == Lexer.Kind.NUMBER || token.kind() == Lexer.Kind.STRING) {
            take();
            return new Literal(token.kind() == Lexer.Kind.NUMBER
                                   ? ValuesFields.number(Integer.parseInt(token.value()))
                                   : ValuesFields.string(token.value()),
                               token.pos());
        }
        if (token.kind() == Lexer.Kind.NAME || at("$"))
            return lvalue();
        if (accept("(") != null) {
            List<Expr> expressions = expressionList(true);
            expect(")");
            if (expressions.size() == 1)
                return new Paren(expressions.getFirst(), token.pos());
            expect("in");
            return new Membership(expressions, name(), token.pos());
        }
        if (token.kind() == Lexer.Kind.FUNCNAME || token.kind() == Lexer.Kind.BUILTIN) {
            take();
            List<Expr> arguments = new ArrayList<>();
            if (accept("(") != null) {
                if (!at(")"))
                    arguments = expressionList(true);
                expect(")");
            } else if (token.kind() == Lexer.Kind.FUNCNAME || !token.text().equals("length"))
                fail();
            if (token.kind() == Lexer.Kind.BUILTIN) {
                checkBuiltin(token, arguments);
                return new Builtin(token.text(), arguments, token.pos());
            }
            return new Call(token.text(), arguments, token.pos());
        }
        if (accept("getline") != null) {
            Expr target = peek().kind() == Lexer.Kind.NAME || at("$") ? lvalue() : null;
            Expr filename = accept("<") != null ? atom() : null;
            return new Getline(target, filename, token.pos());
        }
        fail();
        throw new AssertionError();
    }
    void checkBuiltin(Lexer.Token token, List<Expr> arguments) {
        int count = arguments.size();
        boolean valid = switch (token.text()) {
            case "length" -> count == 0 || count == 1;
            case "substr", "split" -> count == 2 || count == 3;
            case "index" -> count == 2;
            case "sprintf" -> count >= 1;
            default -> count == 1;
        };
        if (!valid || token.text().equals("split") && !(arguments.get(1) instanceof Variable))
            fail(token.pos());
    }
}

import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.io.IOException;
import java.util.*;
final class Streams {
    record Option(String name, String value) {}
    static final class Operand {
        final boolean file;
        final String name, value;
        int records;
        Operand(boolean file, String name, String value) {
            this.file = file;
            this.name = name;
            this.value = value;
        }
    }
    record Arguments(List<Option> options, List<Operand> operands) {}
    record Read(int status, String line) {}
    static boolean validName(String name) {
        if (name.isEmpty() || !Lexer.letter(name.charAt(0)))
            return false;
        for (int i = 1; i < name.length(); i++)
            if (!Lexer.letter(name.charAt(i)) && !Lexer.digit(name.charAt(i)))
                return false;
        return true;
    }
    static boolean validFilename(String name) {
        if (name.isEmpty() || name.charAt(0) == '.')
            return false;
        for (int i = 0; i < name.length(); i++) {
            char c = name.charAt(i);
            if (!Lexer.letter(c) && !Lexer.digit(c) && ".-".indexOf(c) < 0)
                return false;
        }
        return true;
    }
    static List<String> lines(String text) {
        List<String> result = new ArrayList<>();
        int start = 0;
        for (int i = 0; i < text.length(); i++)
            if (text.charAt(i) == '\n') {
                result.add(text.substring(start, i));
                start = i + 1;
            }
        if (start < text.length())
            result.add(text.substring(start));
        return result;
    }
    static List<String> records(String name) throws IOException {
        return lines(Files.readString(Path.of("input", name), StandardCharsets.US_ASCII));
    }
    static Arguments parse(String text) {
        List<Option> options = new ArrayList<>();
        List<Operand> operands = new ArrayList<>();
        for (String line : lines(text)) {
            int equal = line.indexOf('=');
            if (line.startsWith("-F "))
                options.add(new Option("FS", line.substring(3)));
            else if (line.startsWith("-v ")) {
                equal = line.indexOf('=', 3);
                options.add(new Option(line.substring(3, equal), line.substring(equal + 1)));
            } else if (equal >= 0 && validName(line.substring(0, equal)))
                operands.add(
                    new Operand(false, line.substring(0, equal), line.substring(equal + 1)));
            else
                operands.add(new Operand(true, line, null));
        }
        return new Arguments(options, operands);
    }
    static final class Output {
        final StringBuilder content = new StringBuilder();
        boolean open;
        int writes;
        void append(String text) {
            content.append(text);
            writes++;
        }
    }
    static final class Input {
        boolean open, everOpened;
        List<String> lines = List.of();
        int position, reads;
    }
    final Output stdout = new Output();
    final LinkedHashMap<String, Output> outputs = new LinkedHashMap<>();
    final LinkedHashMap<String, Input> inputs = new LinkedHashMap<>();
    void write(String text, String name, String mode, Lexer.Position pos) {
        if (name == null) {
            stdout.append(text);
            return;
        }
        if (!validFilename(name) || name.equals("stdout.txt") || name.equals("stats.txt"))
            throw new Builtins.RuntimeIssue(pos, "invalid output file name");
        Output output = outputs.computeIfAbsent(name, key -> new Output());
        if (!output.open) {
            output.open = true;
            if (mode.equals(">"))
                output.content.setLength(0);
        }
        output.append(text);
    }
    Read getline(String name) throws IOException {
        Input input = inputs.computeIfAbsent(name, key -> new Input());
        if (!input.open) {
            if (!validFilename(name) || !Files.isRegularFile(Path.of("input", name)))
                return new Read(-1, null);
            input.lines = records(name);
            input.position = 0;
            input.open = true;
            input.everOpened = true;
        }
        if (input.position == input.lines.size())
            return new Read(0, null);
        input.reads++;
        return new Read(1, input.lines.get(input.position++));
    }
    int close(String name) {
        boolean closed = false;
        Output output = outputs.get(name);
        if (output != null && output.open) {
            output.open = false;
            closed = true;
        }
        Input input = inputs.get(name);
        if (input != null && input.open) {
            input.open = false;
            closed = true;
        }
        return closed ? 0 : -1;
    }
    void save() throws IOException {
        Files.createDirectories(Path.of("output"));
        Files.writeString(Path.of("output/stdout.txt"), stdout.content, StandardCharsets.US_ASCII);
        for (var entry : outputs.entrySet())
            Files.writeString(Path.of("output", entry.getKey()), entry.getValue().content,
                              StandardCharsets.US_ASCII);
    }
}

import java.util.*;
import java.util.function.Function;
final class ValuesFields {
    enum Kind { NUMBER, STRING, STRNUM, UNINITIALIZED }
    record Value(Kind kind, String text, int numeric) {}
    static final Value UNINITIALIZED = new Value(Kind.UNINITIALIZED, null, 0);
    static Value number(int value) { return new Value(Kind.NUMBER, null, value); }
    static Value string(String value) { return new Value(Kind.STRING, value, 0); }
    static boolean whitespace(char c) { return c == ' ' || c == '\t' || c == '\n'; }
    static int numericPrefix(String text) {
        int index = 0, sign = 1, result = 0;
        while (index < text.length() && whitespace(text.charAt(index)))
            index++;
        if (index < text.length() && (text.charAt(index) == '+' || text.charAt(index) == '-')) {
            if (text.charAt(index) == '-')
                sign = -1;
            index++;
        }
        while (index < text.length() && Lexer.digit(text.charAt(index)))
            result = result * 10 + text.charAt(index++) - '0';
        return sign * result;
    }
    static Value input(String text) {
        int start = 0, end = text.length();
        while (start < end && whitespace(text.charAt(start)))
            start++;
        while (end > start && whitespace(text.charAt(end - 1)))
            end--;
        int digits = start;
        if (digits < end && (text.charAt(digits) == '+' || text.charAt(digits) == '-'))
            digits++;
        boolean numeric = digits < end;
        for (int i = digits; i < end; i++)
            if (!Lexer.digit(text.charAt(i)))
                numeric = false;
        return numeric ? new Value(Kind.STRNUM, text, numericPrefix(text)) : string(text);
    }
    static int numeric(Value value) {
        return value.kind() == Kind.STRING ? numericPrefix(value.text()) : value.numeric();
    }
    static String text(Value value) {
        return switch (value.kind()) {
            case NUMBER -> Integer.toString(value.numeric());
            case UNINITIALIZED -> "";
            default -> value.text();
        };
    }
    static boolean truth(Value value) {
        return value.kind() == Kind.STRING ? !value.text().isEmpty() : value.numeric() != 0;
    }
    static int compare(Value first, Value second) {
        return first.kind() != Kind.STRING && second.kind() != Kind.STRING
            ? Integer.compare(numeric(first), numeric(second))
            : text(first).compareTo(text(second));
    }
    static boolean integerKey(String text) {
        if (text.equals("0"))
            return true;
        int start = text.startsWith("-") ? 1 : 0;
        if (start == text.length() || text.charAt(start) < '1' || text.charAt(start) > '9')
            return false;
        for (int i = start + 1; i < text.length(); i++)
            if (!Lexer.digit(text.charAt(i)))
                return false;
        return true;
    }
    static final Comparator<String> KEY_ORDER = (first, second) -> {
        boolean a = integerKey(first), b = integerKey(second);
        return a && b ? Integer.compare(Integer.parseInt(first), Integer.parseInt(second))
        : a           ? -1
        : b           ? 1
                      : first.compareTo(second);
    };
    static List<String> split(String text, String separator) {
        List<String> result = new ArrayList<>();
        if (text.isEmpty())
            return result;
        if (separator.isEmpty()) {
            for (int i = 0; i < text.length(); i++)
                result.add(text.substring(i, i + 1));
        } else if (separator.equals(" ")) {
            int start = -1;
            for (int i = 0; i < text.length(); i++) {
                if (whitespace(text.charAt(i))) {
                    if (start >= 0) {
                        result.add(text.substring(start, i));
                        start = -1;
                    }
                } else if (start < 0)
                    start = i;
            }
            if (start >= 0)
                result.add(text.substring(start));
        } else {
            int start = 0, next;
            while ((next = text.indexOf(separator, start)) >= 0) {
                result.add(text.substring(start, next));
                start = next + separator.length();
            }
            result.add(text.substring(start));
        }
        return result;
    }
    static final class Record {
        final Function<String, Value> special;
        Value zero = string("");
        final List<Value> fields = new ArrayList<>();
        Record(Function<String, Value> special) { this.special = special; }
        void set(String text) {
            zero = input(text);
            fields.clear();
            for (String piece : split(text, text(special.apply("FS"))))
                fields.add(input(piece));
        }
        Value read(int index) {
            return index == 0        ? zero
            : index <= fields.size() ? fields.get(index - 1)
                                     : UNINITIALIZED;
        }
        void rebuild() {
            StringJoiner joined = new StringJoiner(text(special.apply("OFS")));
            for (Value value : fields)
                joined.add(text(value));
            zero = input(joined.toString());
        }
        void write(int index, Value value) {
            if (index == 0) {
                set(text(value));
                return;
            }
            while (fields.size() < index)
                fields.add(string(""));
            fields.set(index - 1, value);
            rebuild();
        }
        void resize(int size) {
            while (fields.size() > size)
                fields.removeLast();
            while (fields.size() < size)
                fields.add(string(""));
            rebuild();
        }
    }
    static String quoted(String text) {
        StringBuilder result = new StringBuilder("\"");
        for (int i = 0; i < text.length(); i++) {
            char c = text.charAt(i);
            result.append(switch (c) {
                case '"' -> "\\\"";
                case '\\' -> "\\\\";
                case '\n' -> "\\n";
                case '\t' -> "\\t";
                default ->
                    c >= 32 && c <= 126 ? String.valueOf(c)
                                        : "\\" + String.format(Locale.ROOT, "%03o", (int)c);
            });
        }
        return result.append('"').toString();
    }
    static String describe(Value value) {
        return switch (value.kind()) {
            case NUMBER -> Integer.toString(value.numeric());
            case UNINITIALIZED -> "(uninitialized)";
            default -> quoted(value.text()) + (value.kind() == Kind.STRNUM ? " (strnum)" : "");
        };
    }
}
